      "id": "story.world_days",
      "tiers": [
        {
          "id": "story.world_days:t1",
          "title": "Коврик тебя помнит",
          "phrase": "В твоей истории уже 3 разных дня в одном сюжетном мире. Даже местный коврик узнаёт твои шаги.",
          "imagePrompt": "A small fox with an oversized satchel knocks on a crooked mushroom cottage door. The welcome mat curls up to greet its familiar boots, while a little porch stool waits beside the entrance.",
          "fishMarkup": "[warm] В твоей истории уже 3 разных дня в одном сюжетном мире. [playful] Даже местный коврик узнаёт твои шаги.",
          "audioText": "В твоей истории уже 3 разных дня в одном сюжетном мире. Даже местный коврик узнаёт твои шаги."
        },
        {
          "id": "story.world_days:t2",
          "title": "Крючок для своих",
          "phrase": "Ты возвращаешься в один сюжетный мир уже 7 разных дней. Для твоего рюкзака здесь явно пора выделить личный крючок.",
          "imagePrompt": "A small fox hangs its oversized satchel on a dedicated wooden hook beside a crooked mushroom cottage door. The door leans open expectantly, and the curled welcome mat offers a tiny leaf in greeting.",
          "fishMarkup": "[confident] Ты возвращаешься в один сюжетный мир уже 7 разных дней. [playful] Для твоего рюкзака здесь явно пора выделить <emphasis>личный крючок.</emphasis>",
          "audioText": "Ты возвращаешься в один сюжетный мир уже 7 разных дней. Для твоего рюкзака здесь явно пора выделить личный крючок."
        },
        {
          "id": "story.world_days:t3",
          "title": "Домик подаёт тапочки",
          "phrase": "В твоей истории уже 15 разных дней в одном сюжетном мире. Теперь домик сам выносит тебе тапочки.",
          "imagePrompt": "A small fox with an oversized satchel watches a crooked mushroom cottage bend down on root legs and extend a tray of fluffy slippers in its root arms. The familiar welcome mat has rolled itself into a tiny footstool.",
          "fishMarkup": "[triumphant] В твоей истории уже 15 разных дней в одном сюжетном мире. <slow>Теперь домик</slow> [pause] сам выносит тебе тапочки.",
          "audioText": "В твоей истории уже 15 разных дней в одном сюжетном мире. Теперь домик сам выносит тебе тапочки."
        }
      ]
    },
    {
      "id": "story.explorer",
      "tiers": [
        {
          "id": "story.explorer:t1",
          "title": "Багаж с сюжетом",
          "phrase": "Ты сохранил тренировки в 3 разных сюжетных мирах. Твой спортивный чемодан явно вместительнее, чем кажется.",
          "imagePrompt": "A walking suitcase with gloved hands and hiking boots holds its lid open, revealing a jungle vine, a tiny rocket, and a castle turret tucked into separate compartments. Its handle curls upward in surprise.",
          "fishMarkup": "[warm] Ты сохранил тренировки в 3 разных сюжетных мирах. [playful] Твой спортивный чемодан явно <emphasis>вместительнее, чем кажется.</emphasis>",
          "audioText": "Ты сохранил тренировки в 3 разных сюжетных мирах. Твой спортивный чемодан явно вместительнее, чем кажется."
        },
        {
          "id": "story.explorer:t2",
          "title": "Чемодан широких взглядов",
          "phrase": "В 6 разных сюжетных мирах уже есть твои сохранённые тренировки. Чемодан освоил профессию межмирового грузчика.",
          "imagePrompt": "A walking suitcase with gloved hands and hiking boots balances six miniature doorways on a fold-out luggage rack. Jungle leaves, lunar rocks, ocean spray, desert dunes, castle stairs, and snowy peaks spill from the openings.",
          "fishMarkup": "[confident] В 6 разных сюжетных мирах уже есть твои сохранённые тренировки. [playful] Чемодан освоил профессию <emphasis>межмирового грузчика.</emphasis>",
          "audioText": "В 6 разных сюжетных мирах уже есть твои сохранённые тренировки. Чемодан освоил профессию межмирового грузчика."
        },
        {
          "id": "story.explorer:t3",
          "title": "Сам себе туроператор",
          "phrase": "В 10 разных сюжетных мирах ты сохранил тренировки. Чемодан теперь сам выдаёт порталы — вот тебе и ручная кладь.",
          "imagePrompt": "A walking suitcase with gloved hands and hiking boots unfolds into a travel counter surrounded by ten tiny world portals. One hand reaches into a jungle portal and emerges from a lunar portal to shake its other hand.",
          "fishMarkup": "[triumphant] В 10 разных сюжетных мирах ты сохранил тренировки. Чемодан теперь сам выдаёт порталы — [pause] <emphasis>вот тебе и ручная кладь.</emphasis>",
          "audioText": "В 10 разных сюжетных мирах ты сохранил тренировки. Чемодан теперь сам выдаёт порталы — вот тебе и ручная кладь."
        }
      ]
    }
  ]
}
